/bin/bash -lc "python - <<'PY'
import importlib.metadata as md
meta = md.metadata('phe')
for key in ['Name','Version','Summary','Home-page','Author','Author-email','License','Requires-Dist']:
    vals = meta.get_all(key)
    if vals:
        for v in vals:
            print(f'{key}: {v}')
PY"

